# Code generated by Claude
"""
Measurement only: at every phase boundary of a left_arm_motion_measure output, the largest one-tick change of the commanded joint velocity within +-0.1 s of the boundary (the
commanded velocity is the finite difference of the commanded position at 150 Hz), the joint it is on, and the largest commanded speed within 0.3 s after it.

    python experiments/boundary_cmd_steps.py DIR [OTHER_DIR]       (with OTHER_DIR the two are printed side by side)
"""
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent))
from left_arm_motion_report import derive, load  # noqa: E402


def table(d):
    D = load(d)
    tk = derive(D)["tick"]
    t, cv = tk["t"][1:], tk["cv"]
    dcv = np.abs(np.diff(cv, axis=0))
    td = t[1:]
    rows = {}
    for p in D["phases"]:
        if p["t_start"] is None or p["tick"] == 0:
            continue
        b = p["t_start"]
        m = (td >= b - 0.1) & (td < b + 0.1)
        if not m.any():
            continue
        k = int(np.argmax(dcv[m].max(axis=1)))
        ms = (t >= b) & (t < b + 0.3)
        rows[p["key"].split(" ", 1)[1]] = (float(dcv[m].max()), int(np.argmax(dcv[m][k])) + 1, float(np.abs(cv[ms]).max()) if ms.any() else float("nan"))
    return rows


A = table(sys.argv[1])
B = table(sys.argv[2]) if len(sys.argv) > 2 else None
print(f"{'boundary (into)':24s} step rad/s (joint) | max cmd speed in 0.3 s" + ("   || other" if B else ""))
for k, (s, j, m) in A.items():
    line = f"{k:24s} {s:6.3f} (j{j}) | {m:5.3f}"
    if B and k in B:
        line += f"   || {B[k][0]:6.3f} (j{B[k][1]}) | {B[k][2]:5.3f}"
    print(line)
